import React from 'react';

export function TarjetaCurso({ titulo }) {
  const anio = 2024;
  return (
    <div className="tarjeta">
      <h2>{titulo}</h2>
      <span>Año: {anio}</span>
    </div>
  );
}

export function TarjetaUsuario({ nombre, rol, activo }) {
  return (
    <div className="tarjeta">
      <h3>{nombre}</h3>
      <p>Rol: {rol}</p>
      <span className={activo ? "badge-activo" : "badge-inactivo"}>
        {activo ? "En línea" : "Desconectado"}
      </span>
    </div>
  );
}

import React, { useState } from 'react';

export function Contador() {
  const [contador, setContador] = useState(0);

  function incrementar() {
    setContador(contador + 1);
  }

  return (
    <div>
      <p>Valor actual: {contador}</p>
      <button onClick={incrementar}>Sumar</button>
    </div>
  );
}

import React, { useState } from 'react';
export default function TodoApp() {
  const [tasks, setTasks] = useState([]);
  const [input, setInput] = useState('');
  const addTask = (e) => {
    e.preventDefault();
    if (!input.trim()) return;
    setTasks([...tasks, { id: Date.now(), text: input }]);
    setInput('');
  };
  return (
    <div>
      <form onSubmit={addTask}>
        <input value={input} onChange={(e) => setInput(e.target.value)} />
        <button type="submit">Agregar</button>
      </form>
      <ul>{tasks.map(t => <li key={t.id}>{t.text}</li>)}</ul>
    </div>
  );
}

import { useState, useEffect } from 'react';

export function UserProfile({ userId }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    fetch(`https://api.example.com/users/${userId}`)
      .then(res => res.json())
      .then(data => setUser(data));
  }, [userId]);

  return <div>{user ? user.name : 'Cargando...'}</div>;
}

import { useState } from 'react';

export function ListaInvalida() {
  const [items, setItems] = useState(['Elemento 1']);

  const agregarItemIncorrecto = () => {
    items.push('Elemento 2'); // ERROR: Modificación directa
    setItems(items);
  };

  const agregarItemCorrecto = () => {
    setItems([...items, 'Elemento 2']); // CORRECTO: Inmutabilidad
  };

  return <div>Resultado</div>;
}
